// visor-expediente.component.ts (CORREGIDO COMPLETO)
import { Component, Input, Output, EventEmitter, OnInit, OnDestroy, SecurityContext } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { CommonModule } from '@angular/common';
import { SafeHtmlPipe } from '../../../../shared/pipes/safe-html.pipe';
import { ExportService } from '../../services/export.service';

@Component({
  selector: 'app-visor-expediente',
  imports: [CommonModule, SafeHtmlPipe],
  templateUrl: './visor-expediente.component.html',
  styleUrls: ['./visor-expediente.component.less']
})
export class VisorExpedienteComponent implements OnInit, OnDestroy {
  @Input() denuncia: any;
  @Input() modoExpedienteCompleto: boolean = false;
  @Output() cerrar = new EventEmitter<void>();
  @Output() imprimir = new EventEmitter<void>();
  @Output() descargarPDF = new EventEmitter<void>();

  isTurningLeft = false;
  isTurningRight = false;
  private turningTimeout: any;
  paginaActual = 1;
  totalPaginas = 0;
  paginas: any[] = [];
  secciones: any[] = [];

  // Propiedad para saber si el expediente está en préstamo
  estaEnPrestamo = false;
  prestamoActivoInfo: any = null;

  constructor(
    private sanitizer: DomSanitizer,
    private exportService: ExportService
  ) {}

  ngOnInit() {
    this.verificarEstadoPrestamo();
    this.generarPaginas();
  }

  ngOnDestroy() {
    if (this.turningTimeout) {
      clearTimeout(this.turningTimeout);
    }
    if (document.fullscreenElement) {
      document.exitFullscreen().catch(err => {
        console.warn('Error al salir de fullscreen:', err);
      });
    }
  }

  private verificarEstadoPrestamo(): void {
    // Verificar si la denuncia tiene un préstamo activo
    if (this.denuncia.prestamo_activo || this.denuncia.en_prestamo) {
      this.estaEnPrestamo = true;
      this.prestamoActivoInfo = this.denuncia.prestamo_activo;
    } else if (this.denuncia.prestamos && this.denuncia.prestamos.length > 0) {
      // Buscar préstamo activo en el array de préstamos
      const prestamoActivo = this.denuncia.prestamos.find((p: any) =>
        p.estado === 'prestado' || p.estado === 'activo'
      );
      if (prestamoActivo) {
        this.estaEnPrestamo = true;
        this.prestamoActivoInfo = prestamoActivo;
      }
    }
  }

  generarPaginas() {
    // Obtener evidencias reales de la denuncia
    let evidencias: any[] = [];

    // Buscar evidencias en diferentes posibles ubicaciones
    if (this.denuncia.evidencias && Array.isArray(this.denuncia.evidencias)) {
      evidencias = this.denuncia.evidencias;
    } else if (this.denuncia.evidencia_urls) {
      // Convertir objeto de URLs a array
      const evidenciaUrls = this.denuncia.evidencia_urls;
      for (const tipo in evidenciaUrls) {
        if (Array.isArray(evidenciaUrls[tipo])) {
          evidencias.push(...evidenciaUrls[tipo].map((e: any) => ({ ...e, tipo: tipo.replace('s', '') })));
        }
      }
    } else if (this.denuncia.archivos) {
      evidencias = this.denuncia.archivos;
    }

    console.log('📎 Evidencias encontradas:', evidencias.length, evidencias);

    this.paginas = [
      {
        titulo: 'Carátula del Expediente',
        contenido: this.generarCaratula(),
        firma: null
      },
      {
        titulo: 'Información del Denunciante',
        contenido: this.generarInfoDenunciante(),
        firma: null
      },
      {
        titulo: 'Detalles de la Denuncia',
        contenido: this.generarDetallesDenuncia(),
        firma: null
      },
      {
        titulo: 'Estado del Expediente',
        contenido: this.generarEstadoExpediente(),
        firma: null
      },
      {
        titulo: 'Documentos y Evidencias',
        contenido: this.generarEvidencias(evidencias),
        firma: null
      },
      {
        titulo: 'Historial de Préstamos',
        contenido: this.generarHistorialPrestamos(),
        firma: null
      }
    ];

    // Agregar páginas individuales para cada evidencia
    if (evidencias && evidencias.length > 0) {
      evidencias.forEach((evidencia: any, index: number) => {
        this.paginas.push({
          titulo: `Evidencia ${index + 1}: ${evidencia.nombre || evidencia.name || 'Documento'}`,
          contenido: this.generarPaginaEvidencia(evidencia),
          firma: 'Firma del responsable'
        });
      });
    }

    this.totalPaginas = this.paginas.length;
    this.generarSecciones();
  }

  generarCaratula(): string {
    return `
      <div class="data-grid">
        <div class="data-item"><span class="label">Número de Expediente</span><span class="value">${this.denuncia.numero_expediente || this.denuncia.id_denuncia || 'N/A'}</span></div>
        <div class="data-item"><span class="label">Fecha de Ingreso</span><span class="value">${this.formatearFecha(this.denuncia.fecha_creacion || this.denuncia.fecha_ingreso)}</span></div>
        <div class="data-item"><span class="label">Tipo de Denuncia</span><span class="value">${this.denuncia.tipo_denuncia || this.denuncia.tipo_conflicto_nombre || 'N/A'}</span></div>
        <div class="data-item"><span class="label">Estado Actual</span><span class="value">${this.denuncia.estado || this.denuncia.estado_denuncia_nombre || 'REGISTRADA'}</span></div>
      </div>
    `;
  }

  generarInfoDenunciante(): string {
    const denunciante = this.denuncia.denunciante ||
                        this.denuncia.persona?.nombres + ' ' + this.denuncia.persona?.apellidos ||
                        this.denuncia.nombre_completo_denunciante ||
                        'No registrado';
    const documento = this.denuncia.documento || this.denuncia.persona?.numero_documento || 'No registrado';

    return `
      <div class="data-grid">
        <div class="data-item"><span class="label">Denunciante</span><span class="value">${this.escapeHtml(denunciante)}</span></div>
        <div class="data-item"><span class="label">Documento</span><span class="value">${documento}</span></div>
      </div>
    `;
  }

  generarDetallesDenuncia(): string {
    return `
      <h3>Descripción del Hecho</h3>
      <p>${this.escapeHtml(this.denuncia.descripcion || 'Sin descripción detallada')}</p>
      <h3>Observaciones</h3>
      <p>${this.escapeHtml(this.denuncia.observaciones || 'Ninguna observación registrada')}</p>
    `;
  }

  generarEstadoExpediente(): string {
    let estadoHtml = '';

    if (this.estaEnPrestamo) {
      const fechaRetorno = this.prestamoActivoInfo?.fecha_retorno_prevista;
      const esRetrasado = fechaRetorno ? new Date(fechaRetorno) < new Date() : false;

      estadoHtml = `
        <div class="alert alert-warning">
          <span class="alert-icon">⚠️</span>
          <div class="alert-content">
            <strong>${esRetrasado ? 'EXPEDIENTE EN PRÉSTAMO - RETRASADO' : 'EXPEDIENTE EN PRÉSTAMO'}</strong>
            <p>Este expediente se encuentra actualmente prestado.</p>
            ${fechaRetorno ? `<p><strong>Fecha de devolución prevista:</strong> ${this.formatearFecha(fechaRetorno)}</p>` : ''}
            ${esRetrasado ? '<p class="text-danger"><strong>⚠️ LA DEVOLUCIÓN ESTÁ RETRASADA</strong></p>' : ''}
            ${this.prestamoActivoInfo?.personal?.nombre_completo ?
              `<p><strong>En poder de:</strong> ${this.prestamoActivoInfo.personal.nombre_completo}</p>` : ''}
            ${this.prestamoActivoInfo?.motivo ?
              `<p><strong>Motivo:</strong> ${this.prestamoActivoInfo.motivo}</p>` : ''}
          </div>
        </div>
      `;
    } else {
      estadoHtml = `
        <div class="alert alert-success">
          <span class="alert-icon">✅</span>
          <div class="alert-content">
            <strong>EXPEDIENTE DISPONIBLE</strong>
            <p>El expediente se encuentra disponible para préstamo.</p>
          </div>
        </div>
      `;
    }
    return estadoHtml;
  }

  generarEvidencias(evidencias: any[]): string {
    if (!evidencias || evidencias.length === 0) {
      return '<p>No hay evidencias adjuntas a esta denuncia.</p>';
    }

    let html = '<div class="evidence-gallery">';
    evidencias.forEach((ev: any, idx: number) => {
      const nombre = ev.nombre || ev.name || `Evidencia ${idx + 1}`;
      const tipo = ev.tipo || this.getTipoArchivo(nombre);
      const url = ev.url || ev.ruta;

      html += `
        <div class="evidence-card">
          <div class="evidence-icon">${this.getIconoArchivo(tipo)}</div>
          <div class="evidence-info">
            <strong>${this.escapeHtml(nombre)}</strong>
            <small>Tipo: ${tipo}</small>
            ${ev.tamano ? `<small>Tamaño: ${this.formatBytes(ev.tamano)}</small>` : ''}
          </div>
          ${url ? `<button class="btn-view-evidence" onclick="window.open('${url}', '_blank')">Ver</button>` : ''}
        </div>
      `;
    });
    html += '</div>';
    return html;
  }

  generarHistorialPrestamos(): string {
    const prestamos = this.denuncia.prestamos || [];
    if (!prestamos.length) {
      return '<p>No hay registros de préstamos para este expediente.</p>';
    }

    let html = '<table class="data-table"><thead><tr><th>Fecha Préstamo</th><th>Solicitante</th><th>Fecha Devolución Prevista</th><th>Fecha Devolución</th><th>Estado</th></tr></thead><tbody>';
    prestamos.forEach((p: any) => {
      const esRetrasado = p.estado === 'retrasado' || (p.estado === 'prestado' && new Date(p.fecha_retorno_prevista) < new Date());
      html += `<tr>
        <td>${this.formatearFecha(p.fecha_prestamo)}</td>
        <td>${p.solicitante || p.personal?.nombre_completo || 'N/A'}</td>
        <td>${this.formatearFecha(p.fecha_retorno_prevista)}</td>
        <td>${p.fecha_devolucion ? this.formatearFecha(p.fecha_devolucion) : 'Pendiente'}</td>
        <td><span class="estado-badge estado-${p.estado} ${esRetrasado ? 'estado-retrasado' : ''}">
          ${p.estado === 'prestado' ? (esRetrasado ? 'RETRASADO' : 'PRESTADO') : (p.estado || 'DESCONOCIDO')}
        </span></td>
      </tr>`;
    });
    html += '</tbody></table>';
    return html;
  }

  generarPaginaEvidencia(evidencia: any): string {
    const url = evidencia.url || evidencia.ruta;
    const nombre = evidencia.nombre || evidencia.name || 'Documento';
    const tipo = evidencia.tipo || this.getTipoArchivo(nombre);

    let previewHtml = '';
    if (url && (tipo === 'foto' || tipo === 'image')) {
      previewHtml = `<div class="evidence-preview"><img src="${url}" alt="Vista previa" style="max-width:100%; max-height:400px;"></div>`;
    } else if (url && tipo === 'pdf') {
      previewHtml = `<div class="evidence-preview"><iframe src="${url}" width="100%" height="500px"></iframe></div>`;
    }

    return `
      <div class="evidence-detail">
        <h3>${this.escapeHtml(nombre)}</h3>
        <p>Tipo: ${tipo}</p>
        ${evidencia.tamano ? `<p>Tamaño: ${this.formatBytes(evidencia.tamano)}</p>` : ''}
        ${evidencia.created_at ? `<p>Fecha de carga: ${this.formatearFecha(evidencia.created_at)}</p>` : ''}
        ${previewHtml}
        ${url ? `<div class="evidence-actions"><a href="${url}" target="_blank" class="btn-download">📥 Descargar archivo</a></div>` : ''}
      </div>
    `;
  }

  generarSecciones() {
    this.secciones = [
      { titulo: 'Carátula', pagina: 1 },
      { titulo: 'Denunciante', pagina: 2 },
      { titulo: 'Detalles', pagina: 3 },
      { titulo: 'Estado Expediente', pagina: 4 },
      { titulo: 'Evidencias', pagina: 5 },
      { titulo: 'Préstamos', pagina: 6 }
    ];
  }

  irAPagina(pagina: number) {
    this.paginaActual = pagina;
  }

  formatearFecha(fecha: any): string {
    if (!fecha) return 'N/A';
    try {
      return new Date(fecha).toLocaleDateString('es-ES', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      });
    } catch {
      return 'N/A';
    }
  }

  formatBytes(bytes: number): string {
    if (!bytes || bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  getTipoArchivo(nombre: string): string {
    const ext = nombre.split('.').pop()?.toLowerCase() || '';
    if (['jpg', 'jpeg', 'png', 'gif', 'webp'].includes(ext)) return 'foto';
    if (['pdf'].includes(ext)) return 'pdf';
    if (['doc', 'docx'].includes(ext)) return 'documento';
    if (['mp4', 'avi', 'mov', 'mkv'].includes(ext)) return 'video';
    if (['mp3', 'wav', 'ogg'].includes(ext)) return 'audio';
    return 'documento';
  }

  getIconoArchivo(tipo: string): string {
    const iconos: Record<string, string> = {
      'foto': '🖼️',
      'pdf': '📑',
      'documento': '📄',
      'video': '🎬',
      'audio': '🎵'
    };
    return iconos[tipo] || '📎';
  }

  escapeHtml(text: string): string {
    if (!text) return '';
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  actualizarPaginas() {
    const paginasTemp = [...this.paginas];
    this.paginas = [];
    setTimeout(() => {
      this.paginas = paginasTemp;
    }, 50);
  }

  paginaAnterior() {
    if (this.paginaActual > 1 && !this.isTurningLeft) {
      this.isTurningLeft = true;
      setTimeout(() => {
        this.paginaActual--;
        this.isTurningLeft = false;
        this.actualizarPaginas();
      }, 300);
    }
  }

  paginaSiguiente() {
    if (this.paginaActual < this.totalPaginas && !this.isTurningRight) {
      this.isTurningRight = true;
      setTimeout(() => {
        this.paginaActual++;
        this.isTurningRight = false;
        this.actualizarPaginas();
      }, 300);
    }
  }

  async exportarPDF() {
    try {
      const denunciaId = this.denuncia?.id_denuncia || this.denuncia?.denuncia_id;
      if (!denunciaId) {
        this.mostrarError('No se puede identificar la denuncia');
        return;
      }
      await this.exportService.exportarExpedientePDF(denunciaId);
      this.mostrarExito('PDF generado correctamente');
    } catch (error) {
      console.error('Error al exportar PDF:', error);
      this.mostrarError('Error al generar el PDF');
    }
  }

  imprimirPagina() {
    window.print();
  }

  toggleFullscreen() {
    const elem = document.querySelector('.book-container') as any;
    if (!document.fullscreenElement) {
      elem?.requestFullscreen();
    } else {
      document.exitFullscreen();
    }
  }

  private mostrarExito(mensaje: string) {
    console.log('✅', mensaje);
  }

  private mostrarError(mensaje: string) {
    console.error('❌', mensaje);
  }
}
