// expediente.component.ts - CORRECCIÓN DE FILTROS
import { Component, OnInit, OnDestroy, inject, signal, computed, AfterViewChecked } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { Subscription } from 'rxjs';
import { trigger, transition, style, animate } from '@angular/animations';
import { ExportService } from '../services/export.service';
import { PrestamoState } from '../store/prestamo.state';
import { PrestamoService } from '../services/prestamo.service';
import { VisorExpedienteComponent } from '../components/visor-expediente/visor-expediente.component';
import { FormularioPrestamoComponent } from '../components/formulario-prestamo/formulario-prestamo.component';
import { TablaPrestamosComponent } from '../components/tabla-prestamos/tabla-prestamos.component';
import { DashboardLayoutComponent } from '../../../layouts/dashboard-layout/dashboard-layout.component';
import { TruncatePipe } from '../../../shared/pipes/truncate.pipe';
import { LoadingService } from '../../../core/services/loading.service';
import { ModuleLoaderService } from '../../../core/services/module-loader.service';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-expediente',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    RouterModule,
    DashboardLayoutComponent,
    VisorExpedienteComponent,
    FormularioPrestamoComponent,
    TablaPrestamosComponent,
    TruncatePipe
  ],
  templateUrl: './expediente.component.html',
  styleUrls: ['./expediente.component.less'],
  animations: [
    trigger('fadeIn', [
      transition(':enter', [style({ opacity: 0 }), animate('200ms', style({ opacity: 1 }))]),
      transition(':leave', [animate('200ms', style({ opacity: 0 }))])
    ]),
    trigger('slideDown', [
      transition(':enter', [style({ opacity: 0, transform: 'translateY(-20px)' }), animate('300ms', style({ opacity: 1, transform: 'translateY(0)' }))])
    ])
  ]
})
export class ExpedienteComponent implements OnInit, OnDestroy, AfterViewChecked {

  // State
  private moduleName = 'Gestión de Expedientes';
  private dataLoaded = false;
  private isMarkedReady = false;
  private viewCheckedCount = 0;
  private prestamoState = inject(PrestamoState);
  private prestamoService = inject(PrestamoService);
  private router = inject(Router);
  private exportService = inject(ExportService);
  private subscriptions: Subscription[] = [];
  private authService = inject(AuthService);
  usuarioActualId: number = 0;

  // Signal state
  prestamos = this.prestamoState.prestamos;
  estadisticas = this.prestamoState.estadisticas;
  denunciasDisponibles = this.prestamoState.denunciasDisponibles;
  personalDisponible = this.prestamoState.personalDisponible;
  isLoading = this.prestamoState.isLoading;
  error = this.prestamoState.error;

  // ========== FILTROS CORREGIDOS ==========

prestamosActivos = computed(() => {
  return this.prestamos().filter(p => p.estado === 'ACTIVO');
});

// PRÉSTAMOS RETRASADOS: Estado 'RETRASADO' (cuando exista)
prestamosRetrasados = computed(() => {
  return this.prestamos().filter(p => p.estado === 'RETRASADO');
});

// HISTORIAL COMPLETO: TODOS los préstamos
historialCompleto = computed(() => {
  return this.prestamos();
});

  // Vista actual
  currentView = signal<'prestamos' | 'historial' | 'retrasados'>('prestamos');

  // Computed para la tabla según la vista seleccionada
  prestamosMostrados = computed(() => {
    const vista = this.currentView();

    switch(vista) {
      case 'prestamos':
        return this.prestamosActivos();      // Solo activos
      case 'retrasados':
        return this.prestamosRetrasados();   // Solo retrasados
      case 'historial':
        return this.historialCompleto();     // Todos
      default:
        return this.prestamosActivos();
    }
  });

  // UI State
  showPrestamoModal = signal(false);
  showVisor = signal(false);
  denunciaSeleccionada = signal<any>(null);
  prestamoSeleccionado = signal<any>(null);

  // Filtros de búsqueda (para filtrar dentro de cada vista)
  filtros = signal({
    estado: 'todos',
    fecha_desde: '',
    fecha_hasta: '',
    personal_id: null as number | null,
    page: 1,
    per_page: 10
  });

  Math = Math;

  constructor(
    private moduleLoader: ModuleLoaderService,
    private loadingService: LoadingService,
  ) {}

  ngOnInit(): void {
    this.cargarDatosIniciales();
    this.moduleLoader.registerComponentInstance(this.moduleName, this);
    this.loadModuleData();
    this.authService.currentUser$.subscribe(user => {
    this.usuarioActualId = user?.usuario_id || 0;});

    // Verificar préstamos retrasados periódicamente
    setInterval(() => {
      this.verificarPrestamosRetrasados();
    }, 60000);
  }




 private verificarPrestamosRetrasados(): void {
  const hoy = new Date();
  const prestamosActuales = this.prestamos();
  let necesitaActualizacion = false;

  prestamosActuales.forEach(prestamo => {
    // Solo verificar préstamos que están prestados
    if (prestamo.estado === 'ACTIVO' && prestamo.fecha_retorno_prevista) {
      const fechaRetorno = new Date(prestamo.fecha_retorno_prevista);
      if (fechaRetorno < hoy) {
        necesitaActualizacion = true;
        // Llamar al servicio para actualizar el estado
        this.prestamoService.actualizarEstadoRetrasado(prestamo.prestamo_id).subscribe({
          next: () => {
            this.cargarDatosIniciales();
          },
          error: (err) => console.error('Error actualizando estado:', err)
        });
      }
    }
  });
}

 private checkAndMarkReady(): void {
  if (this.isMarkedReady) return;

  const hasContent = document.querySelector('.prestamo-expediente-container, .main-content, app-prestamo-expediente');
  const hasData = document.querySelector('.quick-stats, .denuncias-panel, .filtros-container, .table-container');

  console.log(`🔍 [Préstamos] Verificando contenido: hasContent=${!!hasContent}, hasData=${!!hasData}`);

  if (this.dataLoaded && hasContent && hasData) {
    this.markModuleAsReady();
  } else if (this.dataLoaded) {
    setTimeout(() => this.checkAndMarkReady(), 200);
  }
}

  private markModuleAsReady(): void {
    if (this.isMarkedReady) return;
    this.isMarkedReady = true;
    console.log(`🏁 Marcando módulo como listo: ${this.moduleName}`);
    this.moduleLoader.markModuleRendered(this.moduleName);
  }

  private fetchData(url: string): Promise<any> {
    return new Promise(resolve => setTimeout(resolve, 500));
  }

  ngAfterViewChecked() {
    if (this.isMarkedReady) return;
    this.viewCheckedCount++;
    if (this.dataLoaded && this.viewCheckedCount >= 2) {
      console.log(`✅ Vista completamente estable (afterViewChecked x${this.viewCheckedCount})`);
      this.checkAndMarkReady();
    }
  }

  private async loadModuleData(): Promise<void> {
    try {
      console.log(`📡 Cargando datos para: ${this.moduleName}`);
      await Promise.all([
        this.fetchData('/api/personal'),
        this.fetchData('/api/tipos-documento'),
        this.fetchData('/api/generos')
      ]);
      this.dataLoaded = true;
      console.log(`✅ Datos cargados para: ${this.moduleName}`);
      setTimeout(() => {
        this.checkAndMarkReady();
      }, 100);
    } catch (error) {
      console.error(`❌ Error cargando datos:`, error);
      this.markModuleAsReady();
    }
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach(sub => sub.unsubscribe());
    this.moduleLoader.markModuleRendered(this.moduleName);
    this.markModuleAsReady();
  }

private cargarDatosIniciales(): void {
  this.prestamoState.loadPrestamos(this.filtros());
  this.prestamoState.loadEstadisticas();
  this.prestamoState.loadDenunciasDisponibles();
  this.prestamoState.loadPersonalDisponible();

  // Ver los estados reales después de que lleguen los datos
  setTimeout(() => {
    const prestamos = this.prestamos();
    console.log('🔍 PRÉSTAMOS FINALES:', prestamos);
    console.log('🔍 ESTADOS REALES:', prestamos.map(p => p.estado));
    console.log('🔍 PRIMER PRÉSTAMO COMPLETO:', prestamos[0]);
  }, 3000);
}

  cambiarVista(vista: 'prestamos' | 'historial' | 'retrasados'): void {
    this.currentView.set(vista);
    // No es necesario recargar, solo cambia el computed que filtra los datos
  }

  aplicarFiltros(): void {
    this.prestamoState.loadPrestamos(this.filtros());
  }

  limpiarFiltros(): void {
    this.filtros.set({
      estado: 'todos',
      fecha_desde: '',
      fecha_hasta: '',
      personal_id: null,
      page: 1,
      per_page: 10
    });
    this.prestamoState.loadPrestamos(this.filtros());
  }

  abrirModalPrestamo(denunciaId?: number): void {
    if (denunciaId) {
      this.prestamoSeleccionado.set({ denuncia_id: denunciaId });
    } else {
      this.prestamoSeleccionado.set(null);
    }
    this.showPrestamoModal.set(true);
  }

  async crearPrestamo(data: any): Promise<void> {
    const success = await this.prestamoState.crearPrestamo(data);
    if (success) {
      this.showPrestamoModal.set(false);
      this.cargarDatosIniciales();
      this.mostrarExito('Préstamo solicitado exitosamente');
    } else {
      this.mostrarError('Error al solicitar préstamo');
    }
  }

  async registrarDevolucion(prestamo: any): Promise<void> {
    if (!this.usuarioActualId) {
    this.mostrarError('No se pudo identificar al usuario actual');
    return;
  }
    const fechaDevolucion = new Date().toISOString();
    const success = await this.prestamoState.registrarDevolucion(prestamo.prestamo_id, {
      fecha_devolucion: fechaDevolucion,
      usuario_recibido_id: this.usuarioActualId,
      observaciones_devolucion: ''
    });

    if (success) {
      this.cargarDatosIniciales();
      this.mostrarExito('Devolución registrada exitosamente');
    } else {
      this.mostrarError('Error al registrar devolución');
    }
  }

  async eliminarPrestamo(id: number): Promise<void> {
    if (confirm('¿Está seguro de eliminar este préstamo?')) {
      const success = await this.prestamoState.eliminarPrestamo(id);
      if (success) {
        this.cargarDatosIniciales();
        this.mostrarExito('Préstamo eliminado exitosamente');
      } else {
        this.mostrarError('Error al eliminar préstamo');
      }
    }
  }

  cerrarVisor(): void {
    this.showVisor.set(false);
    this.denunciaSeleccionada.set(null);
  }

  recargarDenuncias(): void {
    this.prestamoState.loadDenunciasDisponibles();
  }

  imprimirDocumento(): void {
    alert('🖨️ Función de impresión en desarrollo');
  }

  verExpediente(denuncia: any) {
    console.log('🔍 Denuncia seleccionada:', denuncia);
    this.denunciaSeleccionada.set(denuncia);
    this.showVisor.set(true);
  }

  async descargarPDF() {
    const denuncia = this.denunciaSeleccionada();
    if (denuncia) {
      const denunciaId = denuncia.id_denuncia || denuncia.denuncia_id;
      await this.exportService.exportarExpedientePDF(denunciaId);
    }
  }

  getEstadoDenunciaClass(estado: string): string {
    const clases: Record<string, string> = {
      'REGISTRADA': 'estado-registrada',
      'EN_REVISION': 'estado-revision',
      'EN_CONCILIACION': 'estado-conciliacion',
      'RESUELTA': 'estado-resuelto',
      'ARCHIVADA': 'estado-archivado',
      'CERRADA': 'estado-cerrado'
    };
    return clases[estado] || 'estado-default';
  }

  private mostrarExito(mensaje: string): void {
    console.log('✅', mensaje);
    alert(mensaje);
  }

  private mostrarError(mensaje: string): void {
    console.error('❌', mensaje);
    alert('❌ ' + mensaje);
  }
}
