import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { saveAs } from 'file-saver';
import { environment } from '../../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class ExportService {
  private apiUrl = environment.apiUrl;

  constructor(private http: HttpClient) {}

  exportarPrestamosPDF(filtros: any = {}) {
    const params = new URLSearchParams(filtros).toString();
    window.open(`${this.apiUrl}/exportar/prestamos-pdf?${params}`, '_blank');
  }

  exportarPrestamosExcel(filtros: any = {}) {
    const params = new URLSearchParams(filtros).toString();
    window.open(`${this.apiUrl}/exportar/prestamos-excel?${params}`, '_blank');
  }

  exportarPrestamosCSV(filtros: any = {}) {
    const params = new URLSearchParams(filtros).toString();
    window.open(`${this.apiUrl}/exportar/prestamos-csv?${params}`, '_blank');
  }

 async exportarExpedientePDF(denunciaId: number): Promise<void> {
  try {
    console.log('📤 Enviando solicitud PDF para denuncia ID:', denunciaId);

    const response = await this.http.post(
      `${this.apiUrl}/exportar/expediente-pdf`,
      { denuncia_id: denunciaId },  // ← Asegurar que se llama "denuncia_id"
      { responseType: 'blob' }
    ).toPromise();

    saveAs(response as Blob, `expediente_${denunciaId}.pdf`);
  } catch (error) {
    console.error('Error exportando PDF:', error);
    throw error;
  }
}
}
