import { Component, Input, Output, EventEmitter, computed, signal, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TruncatePipe } from '../../../../shared/pipes/truncate.pipe';

@Component({
  selector: 'app-tabla-prestamos',
  standalone: true,
  imports: [CommonModule, FormsModule, TruncatePipe],
  templateUrl: './tabla-prestamos.component.html',
  styleUrls: ['./tabla-prestamos.component.less'],
})
export class TablaPrestamosComponent implements OnInit, OnDestroy {
  @Input() prestamos: any[] = [];
  @Input() vista: 'prestamos' | 'historial' | 'retrasados' = 'prestamos';
  @Input() denuncias: any[] = [];
  @Input() personal: any[] = [];
  @Output() verDetalle = new EventEmitter<any>();
  @Output() devolver = new EventEmitter<any>();
  @Output() eliminar = new EventEmitter<number>();

  private intervalId: any;

  get titulo(): string {
    switch (this.vista) {
      case 'prestamos': return 'Préstamos Activos';
      case 'historial': return 'Historial de Préstamos';
      case 'retrasados': return 'Préstamos Retrasados';
      default: return 'Préstamos';
    }
  }

  ngOnInit(): void {
    // Verificar estado de préstamos cada minuto
    this.intervalId = setInterval(() => {
      this.verificarEstadosRetrasados();
    }, 60000);
  }

  ngOnDestroy(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
    }
  }

  public verificarEstadosRetrasados(): void {
    const hoy = new Date();
    let cambios = false;

    this.prestamos.forEach(prestamo => {
      // Si está activo/prestado y la fecha de devolución ya pasó
      if ((prestamo.estado === 'ACTIVO' || prestamo.estado === 'prestado') && prestamo.fecha_retorno_prevista) {
        const fechaRetorno = new Date(prestamo.fecha_retorno_prevista);
        if (fechaRetorno < hoy && prestamo.estado !== 'retrasado') {
          prestamo.estado = 'retrasado';
          cambios = true;
        }
      }
    });

    // Si hubo cambios, notificar al padre para actualizar en backend
    if (cambios) {
      const prestamosRetrasados = this.prestamos.filter(p => p.estado === 'retrasado');
      console.log('📢 Préstamos actualizados a retrasado:', prestamosRetrasados.length);
    }
  }

  obtenerCodigoDenuncia(idDenuncia: number): string {
    return `DEN-${String(idDenuncia).padStart(4, '0')}`;
  }

  obtenerDescripcionDenuncia(idDenuncia: number): string {
    const denuncia = this.denuncias.find(d => d.id_denuncia === idDenuncia || d.denuncia_id === idDenuncia);
    return denuncia?.descripcion || 'Sin descripción';
  }

  obtenerNombrePersonal(idPersonal: number): string {
    const personal = this.personal.find(p => p.id_personal === idPersonal || p.personal_id === idPersonal);
    return personal?.nombre_completo || 'Desconocido';
  }

  mostrarBotonDevolver(prestamo: any): boolean {
  return prestamo.estado === 'ACTIVO' || prestamo.estado === 'RETRASADO';
}

mostrarBotonEliminar(prestamo: any): boolean {
  return prestamo.estado === 'DEVUELTO';
}

  // Método para forzar actualización de estado retrasado
  actualizarEstadoRetrasado(prestamo: any): boolean {
    if (this.estaRetrasado(prestamo) && prestamo.estado !== 'retrasado') {
      prestamo.estado = 'retrasado';
      return true;
    }
    return false;
  }

  getEstadoClass(estado: string): string {
  const clases: Record<string, string> = {
    ACTIVO: 'estado-prestado',
    PRESTADO: 'estado-prestado',
    DEVUELTO: 'estado-devuelto',
    RETRASADO: 'estado-retrasado'
  };
  return clases[estado] || 'estado-default';
}

getEstadoDisplay(estado: string): string {
  const displays: Record<string, string> = {
    ACTIVO: 'PRESTADO',
    PRESTADO: 'PRESTADO',
    DEVUELTO: 'DEVUELTO',
    RETRASADO: 'RETRASADO'
  };
  return displays[estado] || estado || 'DESCONOCIDO';
}

estaRetrasado(prestamo: any): boolean {
  // Si ya está marcado como RETRASADO
  if (prestamo.estado === 'RETRASADO') return true;
  // Si está ACTIVO y la fecha de devolución ya pasó
  if (prestamo.estado === 'ACTIVO' && prestamo.fecha_retorno_prevista) {
    return new Date(prestamo.fecha_retorno_prevista) < new Date();
  }
  return false;
}
}
