import { Component, Input, Output, EventEmitter, HostListener, inject, CUSTOM_ELEMENTS_SCHEMA } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterModule } from '@angular/router';
import { trigger, transition, style, animate } from '@angular/animations';
import { ThemeService, ThemeType } from '../../shared/features/home/services/theme.service';
import { MenuComponent } from '../menu/menu.component';
import { HeaderComponent } from '../header/header.component';
import { FooterComponent } from '../footer/footer.component';
import { HelpSupportComponent } from '../../modules/dashboard/components/help-support/help-support.component';

@Component({
  selector: 'app-dashboard-layout',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    RouterModule,
    MenuComponent,
    HeaderComponent,
    FooterComponent,
    HelpSupportComponent
  ],
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
  template: `
    <div class="dashboard-container"
         [class.dark-theme]="currentTheme === 'dark'"
         [class.neon-theme]="currentTheme === 'neon'"
         [class.sidebar-collapsed]="isSidebarCollapsed">

      <!-- Menu Component -->
      <app-menu
        [isSidebarCollapsed]="isSidebarCollapsed"
        (toggleSidebar)="onToggleSidebar()"
        (toggleHelpSupport)="onToggleHelpSupport()">
      </app-menu>

      <!-- Main Content -->
      <main class="main-content">
        <!-- Header Component -->
        <app-header
          (toggleNotifications)="onToggleNotifications()"
          (toggleUserMenu)="onToggleUserMenu()"
          (markAllAsRead)="onMarkAllAsRead()"
          (openSearchModal)="onOpenSearchModal()">
        </app-header>

        <!-- Content Projection -->
        <ng-content></ng-content>
      </main>
    </div>
  `,
  styles: [`
    .dashboard-container {
      display: flex;
      min-height: 100vh;
      position: relative;
      transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);

      &.sidebar-collapsed {
        margin-left: -195px;
      }

      .main-content {
        flex: 1;
        margin-left: 280px;
        width: calc(100% - 280px);
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        display: flex;
        flex-direction: column;
      }
    }
  `],
  animations: [
    trigger('fadeIn', [
      transition(':enter', [style({ opacity: 0 }), animate('200ms', style({ opacity: 1 }))]),
      transition(':leave', [animate('200ms', style({ opacity: 0 }))])
    ]),
    trigger('slideDown', [
      transition(':enter', [style({ opacity: 0, transform: 'translateY(-20px)' }), animate('300ms', style({ opacity: 1, transform: 'translateY(0)' }))])
    ])
  ]
})
export class DashboardLayoutComponent {
  @Input() isSidebarCollapsed = false;
  @Output() toggleSidebar = new EventEmitter<void>();

  private themeService = inject(ThemeService);

  currentTheme: ThemeType = 'light';
  isSearchOpen = false;
  isMinimized = false;
  showHelpSupport = false;
  searchQuery = '';
  searchResults: any[] = [];
  showMinimizeNotification = false;
  minimizing = false;

  ngOnInit(): void {
    this.themeService.theme$.subscribe(theme => {
      this.currentTheme = theme;
    });
  }

  onToggleSidebar(): void {
    this.isSidebarCollapsed = !this.isSidebarCollapsed;
    this.toggleSidebar.emit();
  }

  onToggleHelpSupport(): void {
    this.showHelpSupport = !this.showHelpSupport;
  }

  onToggleNotifications(): void {}
  onToggleUserMenu(): void {}
  onMarkAllAsRead(): void {}
  onOpenSearchModal(): void {}
  closeSearchModal(): void {}
  performSearch(): void {}
  clearSearch(): void {}
  minimizeToBubble(): void {}
  restoreFromBubble(): void {}
  closeBubble(event: Event): void {}
  handleOverlayClick(event: MouseEvent): void {}
}
