import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../../../environments/environment';

export interface PrestamoResponse {
  success: boolean;
  data: any;
  message?: string;
  pagination?: {
    current_page: number;
    per_page: number;
    total: number;
    last_page: number;
  };
  estadisticas?: any;
}

@Injectable({ providedIn: 'root' })
export class PrestamoService {
  private http = inject(HttpClient);
  private baseUrl = `${environment.apiUrl}/prestamos`;

  listarPrestamos(filters?: any): Observable<PrestamoResponse> {
    let params = new HttpParams();

    if (filters) {
      Object.entries(filters).forEach(([key, value]) => {
        if (value !== null && value !== undefined && value !== '') {
          params = params.set(key, value.toString());
        }
      });
    }

    return this.http.get<PrestamoResponse>(this.baseUrl, { params });
  }

  obtenerPrestamo(id: number): Observable<PrestamoResponse> {
    return this.http.get<PrestamoResponse>(`${this.baseUrl}/${id}`);
  }

  crearPrestamo(data: any): Observable<PrestamoResponse> {
    return this.http.post<PrestamoResponse>(this.baseUrl, data);
  }

  actualizarPrestamo(id: number, data: any): Observable<PrestamoResponse> {
    return this.http.put<PrestamoResponse>(`${this.baseUrl}/${id}`, data);
  }

  registrarDevolucion(id: number, data: any): Observable<PrestamoResponse> {
    return this.http.post<PrestamoResponse>(`${this.baseUrl}/${id}/devolucion`, data);
  }

  eliminarPrestamo(id: number): Observable<PrestamoResponse> {
    return this.http.delete<PrestamoResponse>(`${this.baseUrl}/${id}`);
  }

  getEstadisticas(): Observable<PrestamoResponse> {
    return this.http.get<PrestamoResponse>(`${this.baseUrl}/estadisticas`);
  }

  getPrestamosActivos(): Observable<PrestamoResponse> {
    return this.http.get<PrestamoResponse>(`${this.baseUrl}/activos`);
  }

  getPrestamosRetrasados(): Observable<PrestamoResponse> {
    return this.http.get<PrestamoResponse>(`${this.baseUrl}/retrasados`);
  }

  getHistorial(): Observable<PrestamoResponse> {
    return this.http.get<PrestamoResponse>(`${this.baseUrl}/historial`);
  }

  getDenunciasDisponibles(): Observable<PrestamoResponse> {
    return this.http.get<PrestamoResponse>(`${this.baseUrl}/denuncias-disponibles`);
  }

  getPersonalDisponible(): Observable<PrestamoResponse> {
    return this.http.get<PrestamoResponse>(`${this.baseUrl}/personal-disponible`);
  }

  verificarDisponibilidad(denunciaId: number): Observable<PrestamoResponse> {
    return this.http.get<PrestamoResponse>(`${this.baseUrl}/verificar-disponibilidad`, {
      params: new HttpParams().set('denuncia_id', denunciaId.toString())
    });
  }

 actualizarEstadoRetrasado(id: number): Observable<PrestamoResponse> {
    return this.http.patch<PrestamoResponse>(`${this.baseUrl}/${id}/estado`, {
      estado: 'retrasado'
    });
  }

  // Método para obtener todos los préstamos y verificar retrasados automáticamente
  verificarYActualizarRetrasados(): Observable<PrestamoResponse> {
    return this.http.post<PrestamoResponse>(`${this.baseUrl}/verificar-retrasados`, {});
  }

  exportarExcel(filters?: any): Observable<Blob> {
    let params = new HttpParams();

    if (filters) {
      Object.entries(filters).forEach(([key, value]) => {
        if (value) params = params.set(key, value.toString());
      });
    }

    return this.http.get(`${this.baseUrl}/exportar-excel`, {
      params,
      responseType: 'blob'
    });
  }
}
