import { Injectable, signal, computed, inject } from '@angular/core';
import { PrestamoService } from '../services/prestamo.service';

export interface Prestamo {
  prestamo_id: number;
  identificador: string;
  denuncia_id: number;
  personal_id: number;
  fecha_prestamo: string;
  fecha_retorno_prevista: string;
  fecha_devolucion: string | null;
  usuario_recibido_id: number | null;
  estado: 'ACTIVO' | 'DEVUELTO' | 'RETRASADO' | 'PERDIDO';
  motivo: string;
  observaciones_devolucion: string | null;
  denuncia?: any;
  personal?: any;
}

export interface Estadisticas {
  prestamos_activos: number;
  devueltos_hoy: number;
  retrasados: number;
  por_vencer: number;
  total_prestamos: number;
}

export interface DenunciaDisponible {
  id_denuncia: number;
  tipo_denuncia: string;
  estado: string;
  fecha_creacion: string;
  descripcion: string;
  documentos: number;
  total_prestamos: number;
  en_prestamo: boolean;
  prestamo_retrasado?: boolean;
  prestamo_activo?: any;
}

export interface PersonalDisponible {
  id_personal: number;
  nombre_completo: string;
  cargo: string;
}

@Injectable({ providedIn: 'root' })
export class PrestamoState {
  private prestamoService = inject(PrestamoService);

  // Signals
  private prestamosSignal = signal<Prestamo[]>([]);
  private estadisticasSignal = signal<Estadisticas>({
    prestamos_activos: 0,
    devueltos_hoy: 0,
    retrasados: 0,
    por_vencer: 0,
    total_prestamos: 0
  });
  private denunciasDisponiblesSignal = signal<DenunciaDisponible[]>([]);
  private personalDisponibleSignal = signal<PersonalDisponible[]>([]);
  private loadingSignal = signal(false);
  private errorSignal = signal<string | null>(null);

  // Computed signals
  prestamos = computed(() => this.prestamosSignal());
  estadisticas = computed(() => this.estadisticasSignal());
  denunciasDisponibles = computed(() => this.denunciasDisponiblesSignal());
  personalDisponible = computed(() => this.personalDisponibleSignal());
  isLoading = computed(() => this.loadingSignal());
  error = computed(() => this.errorSignal());

  get prestamosActivos() {
    return computed(() => this.prestamosSignal().filter(p => p.estado === 'ACTIVO'));
  }

  get prestamosRetrasados() {
    return computed(() => this.prestamosSignal().filter(p => p.estado === 'RETRASADO'));
  }

  get historial() {
    return computed(() => this.prestamosSignal());
  }


  async loadEstadisticas(): Promise<void> {
    try {
      const response = await this.prestamoService.getEstadisticas().toPromise();
      if (response?.success) {
        this.estadisticasSignal.set(response.data);
      }
    } catch (error: any) {
      console.error('Error loading estadisticas:', error);
    }
  }

  async loadDenunciasDisponibles(): Promise<void> {
    try {
      const response = await this.prestamoService.getDenunciasDisponibles().toPromise();
      if (response?.success) {
        this.denunciasDisponiblesSignal.set(response.data);
      }
    } catch (error: any) {
      console.error('Error loading denuncias:', error);
    }
  }

  async loadPersonalDisponible(): Promise<void> {
    try {
      const response = await this.prestamoService.getPersonalDisponible().toPromise();
      if (response?.success) {
        this.personalDisponibleSignal.set(response.data);
      }
    } catch (error: any) {
      console.error('Error loading personal:', error);
    }
  }

  async crearPrestamo(data: any): Promise<boolean> {
    this.loadingSignal.set(true);
    try {
      const response = await this.prestamoService.crearPrestamo(data).toPromise();
      if (response?.success) {
        await this.loadPrestamos();
        await this.loadEstadisticas();
        await this.loadDenunciasDisponibles();
        return true;
      }
      return false;
    } catch (error: any) {
      this.errorSignal.set(error.message || 'Error al crear préstamo');
      return false;
    } finally {
      this.loadingSignal.set(false);
    }
  }

  async registrarDevolucion(id: number, data: any): Promise<boolean> {
    this.loadingSignal.set(true);
    try {
      const response = await this.prestamoService.registrarDevolucion(id, data).toPromise();
      if (response?.success) {
        await this.loadPrestamos();
        await this.loadEstadisticas();
        await this.loadDenunciasDisponibles();
        return true;
      }
      return false;
    } catch (error: any) {
      this.errorSignal.set(error.message || 'Error al registrar devolución');
      return false;
    } finally {
      this.loadingSignal.set(false);
    }
  }

  async eliminarPrestamo(id: number): Promise<boolean> {
    this.loadingSignal.set(true);
    try {
      const response = await this.prestamoService.eliminarPrestamo(id).toPromise();
      if (response?.success) {
        await this.loadPrestamos();
        await this.loadEstadisticas();
        return true;
      }
      return false;
    } catch (error: any) {
      this.errorSignal.set(error.message || 'Error al eliminar préstamo');
      return false;
    } finally {
      this.loadingSignal.set(false);
    }
  }

  async verificarYActualizarRetrasados(): Promise<void> {
  try {
    const response = await this.prestamoService.verificarYActualizarRetrasados().toPromise();
    if (response?.success) {
      await this.loadPrestamos();
      await this.loadEstadisticas();
    }
  } catch (error: any) {
    console.error('Error verificando retrasados:', error);
  }
}
async actualizarEstadoRetrasado(id: number): Promise<boolean> {
  this.loadingSignal.set(true);
  try {
    const response = await this.prestamoService.actualizarEstadoRetrasado(id).toPromise();
    if (response?.success) {
      await this.loadPrestamos();
      await this.loadEstadisticas();
      return true;
    }
    return false;
  } catch (error: any) {
    this.errorSignal.set(error.message || 'Error al actualizar estado');
    return false;
  } finally {
    this.loadingSignal.set(false);
  }
}

async loadPrestamos(filters?: any): Promise<void> {
  this.loadingSignal.set(true);
  this.errorSignal.set(null);

  try {
    console.log('📡 Llamando a listarPrestamos con filtros:', filters);
    const response = await this.prestamoService.listarPrestamos(filters).toPromise();
    console.log('📥 Respuesta completa de listarPrestamos:', response);

    if (response?.success) {
      console.log('✅ Datos de préstamos recibidos:', response.data);
      console.log('📊 Cantidad de préstamos:', response.data?.length);
      this.prestamosSignal.set(response.data || []);
    } else {
      console.warn('⚠️ Respuesta sin éxito:', response);
      this.prestamosSignal.set([]);
    }
  } catch (error: any) {
    console.error('❌ Error en loadPrestamos:', error);
    this.errorSignal.set(error.message || 'Error al cargar préstamos');
    this.prestamosSignal.set([]);
  } finally {
    this.loadingSignal.set(false);
  }
}


}
